	protected ObjectNode ownerNode() {
		ObjectNode o = om.createObjectNode();
		o.put("firstName", "Test");
		o.put("lastName", uniqueLastName());
		o.put("address", uniqueAddress());
		o.put("city", uniqueCity());
		o.put("telephone", uniqueTelephone());
