356	     * values are returned unchanged.
357	     *
358	     * @param telephone the raw telephone, possibly {@code null}
359	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
360	     *     valid E.164 number
361	     */
362	    public static String normalizeTelephone(String telephone) {
363	        if (telephone == null) {
364	            return null;
365	        }
366	        String trimmed = telephone.trim();
367	        boolean hasCountryCode = trimmed.startsWith("+");
368	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
369	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
370	        if (hasCountryCode) {
371	            stripped = stripped.substring(1);
372	        }
373	        if (!stripped.matches("\\d+")) {
374	            return null;
375	        }
376	        String digits;
377	        if (hasCountryCode) {
378	            digits = stripped;
379	        } else {
380	            if (stripped.startsWith("0")) {
381	                stripped = stripped.substring(1);
382	            }
383	            digits = "61" + stripped;
384	        }
385	        if (digits.length() < 8 || digits.length() > 15) {
386	            return null;
387	        }
388	        if (!hasValidNationalNumberLength(digits)) {
389	            return null;
390	        }
391	        return "+" + digits;
392	    }
393	
394	    /**
395	     * Format a stored E.164 telephone for human display: the country code, a space, then the
396	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
397	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
398	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
399	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
400	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
401	     * kept unchanged elsewhere.
402	     *
403	     * @param telephone the stored E.164 telephone, possibly {@code null}
404	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
405	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
406	     *     unchanged
407	     */
408	    public static String telephoneDisplay(String telephone) {
409	        if (telephone == null) {
410	            return null;
411	        }
412	        if (!telephone.matches("\\+\\d+")) {
413	            return telephone;
414	        }
415	        String digits = telephone.substring(1);
416	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
417	            if (digits.startsWith(countryCode)) {
418	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
419	            }
420	        }
421	        return "+" + groupDigits(digits);
422	    }
423	
424	    /**
425	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
426	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
427	     * {@code "412345678"} becomes {@code "412 345 678"}).
428	     *
429	     * @param digits the national digits
430	     * @return the space-grouped digits
431	     */
432	    private static String groupDigits(String digits) {
433	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
434	        for (int i = 0; i < digits.length(); i++) {
435	            if (i > 0 && i % 3 == 0) {
436	                grouped.append(' ');
437	            }
438	            grouped.append(digits.charAt(i));
439	        }
440	        return grouped.toString();
441	    }
