443	    /**
444	     * Required national-number length (the count of digits after the country code) for each
445	     * recognized country code, longest country code first so the prefix match is unambiguous.
446	     */
447	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
448	    static {
449	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
450	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
451	    }
452	
453	    /**
454	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
455	     * length its country code requires. A country code with no registered length places no
456	     * additional constraint and is accepted.
457	     *
458	     * @param digits the E.164 digits without the leading {@code '+'}
459	     * @return {@code true} if the national-number length is valid for the country code
460	     */
461	    private static boolean hasValidNationalNumberLength(String digits) {
462	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
463	            String countryCode = entry.getKey();
464	            if (digits.startsWith(countryCode)) {
465	                return digits.length() - countryCode.length() == entry.getValue();
466	            }
467	        }
468	        return true;
469	    }
