471	    /**
472	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
473	     * upper-cased abbreviation.
474	     */
475	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
476	        "ST", "STREET",
477	        "RD", "ROAD",
478	        "AVE", "AVENUE");
479	
480	    /**
481	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
482	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
483	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
484	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
485	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
486	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
487	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
488	     * value. The transform is idempotent: a normalized address normalizes to itself.
489	     *
490	     * @param address the raw address, possibly {@code null}
491	     * @return the normalized form, or {@code null} if the input was {@code null}
492	     */
493	    public static String normalizeAddress(String address) {
494	        if (address == null) {
495	            return null;
496	        }
497	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
498	        if (collapsed.isEmpty()) {
499	            return collapsed;
500	        }
501	        String[] tokens = collapsed.split(" ");
502	        StringBuilder normalized = new StringBuilder(collapsed.length());
503	        for (int i = 0; i < tokens.length; i++) {
504	            if (i > 0) {
505	                normalized.append(' ');
506	            }
507	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
508	        }
509	        return normalized.toString();
510	    }
