512	    /**
513	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
514	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
515	     * result is that line, with a single space and {@code addressLine2} appended when the second line
516	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
517	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
518	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
519	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
520	     *
521	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
522	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
523	     * @param flatAddress the normalized flat address, possibly {@code null}
524	     * @return the composed address, or the flat value / {@code null} when no structured line is present
525	     */
526	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
527	        if (isPresent(addressLine1)) {
528	            if (isPresent(addressLine2)) {
529	                return addressLine1 + " " + addressLine2;
530	            }
531	            return addressLine1;
532	        }
533	        return flatAddress;
534	    }
