536	    /**
537	     * Whether an address field supplies a usable value, i.e. is non-{@code null} and not blank. This
538	     * is the shared "presence" rule behind both {@link #composeAddress(String, String, String)} and
539	     * {@link #hasAddress(String, String)}, so they agree on what counts as a supplied address field.
540	     *
541	     * @param value the address field, possibly {@code null}
542	     * @return {@code true} if the value is present and non-blank
543	     */
544	    private static boolean isPresent(String value) {
545	        return value != null && !value.isBlank();
546	    }
547	
548	    /**
549	     * Check whether an owner supplies a postal address in at least one accepted form: a non-blank
550	     * structured {@code addressLine1}, or a non-blank flat {@code address}. This is the single source
551	     * of truth for the address presence rule, shared by the DTO validation and any persistence path.
552	     *
553	     * @param addressLine1 the structured first line, possibly {@code null}
554	     * @param address the flat address, possibly {@code null}
555	     * @return {@code true} if either form supplies a non-blank value, {@code false} otherwise
556	     */
557	    public static boolean hasAddress(String addressLine1, String address) {
558	        return isPresent(addressLine1) || isPresent(address);
559	    }
