561	    /**
562	     * Normalize a household field (such as last name or address) to its canonical form for
563	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
564	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
565	     * that differ only in letter case or spacing are treated as the same value.
566	     *
567	     * @param value the raw field value, possibly {@code null}
568	     * @return the normalized form, or {@code null} if the input was {@code null}
569	     */
570	    public static String normalizeHousehold(String value) {
571	        if (value == null) {
572	            return null;
573	        }
574	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
575	    }
576	
577	    /**
578	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
579	     * last name (compared case-insensitively with collapsed whitespace, see
580	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
581	     * those two fields, so two owners who share a last name and postcode are assigned the same id
582	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
583	     * upper-cased hex characters of the SHA-256 digest of
584	     * {@code normalizedLastName + '|' + postcode}.
585	     *
586	     * @param lastName the owner's last name, possibly {@code null}
587	     * @param postcode the owner's postcode, possibly {@code null}
588	     * @return the household id, or {@code null} if either field is {@code null}
589	     */
590	    public static String householdId(String lastName, String postcode) {
591	        String normalizedLastName = normalizeHousehold(lastName);
592	        if (normalizedLastName == null || postcode == null) {
593	            return null;
594	        }
595	        String key = normalizedLastName + "|" + postcode;
596	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
597	    }
598	
599	    /**
600	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
601	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
602	     * so they all agree on algorithm and encoding.
603	     *
604	     * @param value the string to digest, never {@code null}
605	     * @return the 64-character lower-case hex digest
606	     */
607	    private static String sha256Hex(String value) {
608	        try {
609	            byte[] digest = MessageDigest.getInstance("SHA-256")
610	                .digest(value.getBytes(StandardCharsets.UTF_8));
611	            StringBuilder hex = new StringBuilder(digest.length * 2);
612	            for (byte b : digest) {
613	                hex.append(String.format("%02x", b));
614	            }
615	            return hex.toString();
616	        } catch (NoSuchAlgorithmException e) {
617	            // SHA-256 is a standard algorithm required to be present on every JVM.
618	            throw new IllegalStateException("SHA-256 not available", e);
619	        }
620	    }
621	
622	    /**
623	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
624	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
625	     * <ul>
626	     *   <li>{@code REGION} is the region code derived from the postcode (see
627	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
628	     *       in no known range, and</li>
629	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
630	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
631	     *       name.</li>
632	     * </ul>
633	     * The value is deterministic in the postcode, telephone and last name (e.g.
634	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
635	     *
636	     * @param postcode the owner's postcode, possibly {@code null}
637	     * @param telephone the owner's raw telephone, possibly {@code null}
638	     * @param lastName the owner's last name, possibly {@code null}
639	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
640	     */
641	    public static String customerCode(String postcode, String telephone, String lastName) {
642	        if (telephone == null || lastName == null) {
643	            return null;
644	        }
645	        String region = regionForPostcode(postcode);
646	        if (region == null) {
647	            region = "UNKNOWN";
648	        }
649	        String normalizedTelephone = normalizeTelephone(telephone);
650	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
651	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
652	    }
653	
654	    /**
655	     * Compute an owner's {@code identityKey}, the single derived value through which all
656	     * duplicate detection is now expressed. It is the lower-case hex SHA-256 digest (see
657	     * {@link #sha256Hex(String)}) of the three identity components joined with {@code '|'}:
658	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where
659	     * <ul>
660	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
661	     *   <li>the lower-cased email (see {@link #normalizeEmail(String)}), or the empty string
662	     *       when no email is present, and</li>
663	     *   <li>the Soundex code of the last name (see {@link #soundex(String)}).</li>
664	     * </ul>
665	     * A {@code null} component is rendered as the empty string before hashing. Two owners are the
666	     * same identity only when their <em>whole</em> keys are equal; because the telephone is part of
667	     * the key, two members of the same household (same last name and postcode) with different
668	     * telephones have different keys and are not a hard duplicate.
669	     *
670	     * @param telephone the owner's raw telephone, possibly {@code null}
671	     * @param email the owner's email, possibly {@code null}
672	     * @param lastName the owner's last name, possibly {@code null}
673	     * @return the 64-character lower-case hex identity key, never {@code null}
674	     */
675	    public static String identityKey(String telephone, String email, String lastName) {
676	        String normalizedTelephone = normalizeTelephone(telephone);
677	        String normalizedEmail = normalizeEmail(email);
678	        String lastNameSoundex = soundex(lastName);
679	        String raw = (normalizedTelephone == null ? "" : normalizedTelephone)
680	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
681	            + "|" + (lastNameSoundex == null ? "" : lastNameSoundex);
682	        return sha256Hex(raw);
683	    }
