685	    /** Soundex digit for each consonant; vowels, {@code H}, {@code W} and {@code Y} map to '0'. */
686	    private static final Map<Character, Character> SOUNDEX_CODES = new HashMap<>();
687	    static {
688	        for (char c : "BFPV".toCharArray()) {
689	            SOUNDEX_CODES.put(c, '1');
690	        }
691	        for (char c : "CGJKQSXZ".toCharArray()) {
692	            SOUNDEX_CODES.put(c, '2');
693	        }
694	        for (char c : "DT".toCharArray()) {
695	            SOUNDEX_CODES.put(c, '3');
696	        }
697	        SOUNDEX_CODES.put('L', '4');
698	        for (char c : "MN".toCharArray()) {
699	            SOUNDEX_CODES.put(c, '5');
700	        }
701	        SOUNDEX_CODES.put('R', '6');
702	    }
703	
704	    /**
705	     * Compute the American Soundex code of a name: the upper-cased first letter followed by three
706	     * digits encoding the following consonants ({@code B,F,P,V}->1; {@code C,G,J,K,Q,S,X,Z}->2;
707	     * {@code D,T}->3; {@code L}->4; {@code M,N}->5; {@code R}->6), padded with zeros to length four.
708	     * Vowels ({@code A,E,I,O,U,Y}) separate codes; {@code H} and {@code W} are ignored so two
709	     * like-coded consonants on either side of them collapse to a single digit; adjacent letters with
710	     * the same code also collapse to one. Non-letters are stripped before coding. This is the single
711	     * source of truth for the surname component of the {@code identityKey} and the soft-match rule.
712	     *
713	     * @param name the raw name, possibly {@code null}
714	     * @return the four-character Soundex code, {@code null} if the input is {@code null}, or the empty
715	     *     string if the input contains no letters
716	     */
717	    public static String soundex(String name) {
718	        if (name == null) {
719	            return null;
720	        }
721	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
722	        if (letters.isEmpty()) {
723	            return "";
724	        }
725	        StringBuilder code = new StringBuilder();
726	        code.append(letters.charAt(0));
727	        char previous = SOUNDEX_CODES.getOrDefault(letters.charAt(0), '0');
728	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
729	            char c = letters.charAt(i);
730	            if (c == 'H' || c == 'W') {
731	                continue;
732	            }
733	            char digit = SOUNDEX_CODES.getOrDefault(c, '0');
734	            if (digit != '0' && digit != previous) {
735	                code.append(digit);
736	            }
737	            previous = digit;
738	        }
739	        while (code.length() < 4) {
740	            code.append('0');
741	        }
742	        return code.toString();
743	    }
