751	    /**
752	     * Resolve the fiscal-year number for a date, where the fiscal year starts on 1 July and is
753	     * named for the calendar year in which it ends. A date in July&ndash;December belongs to the
754	     * fiscal year of the next calendar year; a date in January&ndash;June belongs to the fiscal
755	     * year of its own calendar year.
756	     *
757	     * @param date the date to resolve, never {@code null}
758	     * @return the fiscal-year number (a four-digit calendar year)
759	     */
760	    private static int fiscalYearNumber(LocalDate date) {
761	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
762	    }
