798	    /**
799	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
800	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
801	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
802	     * and gains 3 when the owner's tenure is more than one fiscal year (the tenure being the number
803	     * of elapsed fiscal years from {@code registrationDate} to today, see
804	     * {@link #fiscalYear(LocalDate)}). Because a newly created owner has zero tenure, the tenure
805	     * points accrue only once the owner has been a member for more than a full fiscal year.
806	     *
807	     * @param namesakeCount the owner's namesake count, possibly {@code null}
808	     * @param email the owner's email, possibly {@code null}
809	     * @param householdCount the number of members in the owner's household, possibly {@code null}
810	     * @param registrationDate the owner's registration date, possibly {@code null}
811	     * @return the membership points, a non-negative integer
812	     */
813	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
814	            LocalDate registrationDate) {
815	        int points = 0;
816	        if (email != null && !email.isEmpty()) {
817	            points += 2;
818	        }
819	        if (namesakeCount != null && namesakeCount == 0) {
820	            points += 1;
821	        }
822	        if (householdCount != null && householdCount >= 3) {
823	            points += 2;
824	        }
825	        if (registrationDate != null
826	            && fiscalYearNumber(LocalDate.now()) - fiscalYearNumber(registrationDate) > 1) {
827	            points += 3;
828	        }
829	        return points;
830	    }
