832	    /**
833	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
834	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
835	     *
836	     * @param membershipPoints the owner's membership points
837	     * @return the membership level, an integer from 1 to 4
838	     */
839	    public static int membershipLevel(int membershipPoints) {
840	        if (membershipPoints >= 6) {
841	            return 4;
842	        }
843	        if (membershipPoints >= 4) {
844	            return 3;
845	        }
846	        if (membershipPoints >= 2) {
847	            return 2;
848	        }
849	        return 1;
850	    }
