875	    private static final Map<String, String> CITY_REGION = Map.of(
876	        "Sydney", "NSW",
877	        "Melbourne", "VIC",
878	        "Brisbane", "QLD");
879	
880	    /**
881	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
882	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
883	     * Because the customer code's region is itself derived from the postcode, the locality now shares
884	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
885	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
886	     *
887	     * @param customerCode the owner's customer code, possibly {@code null}
888	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
889	     */
890	    public static String locality(String customerCode) {
891	        if (customerCode == null) {
892	            return "UNKNOWN";
893	        }
894	        int dash = customerCode.indexOf('-');
895	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
896	    }
897	
898	    /**
899	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
900	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
901	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
902	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
903	     */
904	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
905	        "NSW", "Australia/Sydney",
906	        "VIC", "Australia/Melbourne",
907	        "QLD", "Australia/Brisbane");
908	
909	    /**
910	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
911	     * from the fixed {@link #REGION_TIMEZONE} table ({@code NSW}->{@code Australia/Sydney},
912	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). The region
913	     * is the owner's {@code locality} (see {@link #locality(String)}), itself the {@code REGION}
914	     * segment of the customer code. A region not in the table (including {@code 'UNKNOWN'}) has no
915	     * timezone and yields {@code null}.
916	     *
917	     * @param customerCode the owner's customer code, possibly {@code null}
918	     * @return the IANA timezone name, or {@code null} when the owner's region has no mapped timezone
919	     */
920	    public static String timezone(String customerCode) {
921	        return REGION_TIMEZONE.get(locality(customerCode));
922	    }
923	
924	    /**
925	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
926	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
927	     *
928	     * @param city the owner's city, possibly {@code null}
929	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
930	     */
931	    private static String regionForCity(String city) {
932	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
933	    }
934	
935	    /**
936	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
937	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
938	     * inclusive low and high bound of the region's valid 4-digit postcodes
939	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
940	     * table (including {@code 'UNKNOWN'}) places no range constraint.
941	     */
942	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
943	        "NSW", new int[] {2000, 2099},
944	        "VIC", new int[] {3000, 3099},
945	        "QLD", new int[] {4000, 4099});
946	
947	    /**
948	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
949	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
950	     * digits, or one that falls in no known range resolves to {@code null}.
951	     *
952	     * @param postcode the owner's postcode, possibly {@code null}
953	     * @return the matching region, or {@code null} when no range contains the postcode
954	     */
955	    private static String regionForPostcode(String postcode) {
956	        if (postcode == null || !postcode.matches("\\d{4}")) {
957	            return null;
958	        }
959	        int value = Integer.parseInt(postcode);
960	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
961	            int[] range = entry.getValue();
962	            if (value >= range[0] && value <= range[1]) {
963	                return entry.getKey();
964	            }
965	        }
966	        return null;
967	    }
968	
969	    /**
970	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
971	     * {@code null} or empty postcode is always valid. When present it must be exactly four
972	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
973	     * range the value must fall within that inclusive range. A city with no known region accepts
974	     * any four-digit postcode. This is the single source of
975	     * truth for postcode validity, shared by the DTO validation and any persistence path.
976	     *
977	     * @param postcode the owner's postcode, possibly {@code null}
978	     * @param city the owner's city, possibly {@code null}
979	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
980	     */
981	    public static boolean isPostcodeValidForCity(String postcode, String city) {
982	        if (postcode == null || postcode.isEmpty()) {
983	            return true;
984	        }
985	        if (!postcode.matches("\\d{4}")) {
986	            return false;
987	        }
988	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
989	        if (range == null) {
990	            return true;
991	        }
992	        int value = Integer.parseInt(postcode);
993	        return value >= range[0] && value <= range[1];
994	    }
995	
996	    /**
997	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
998	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
999	     * value is deterministic in the customer code and is the standard Luhn check digit: each
1000	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
1001	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
1002	     * brings the weighted sum up to the next multiple of ten.
1003	     *
1004	     * @param customerCode the owner's customer code, possibly {@code null}
1005	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
1006	     */
1007	    public static Integer checkDigit(String customerCode) {
1008	        if (customerCode == null) {
1009	            return null;
1010	        }
1011	        int sum = 0;
1012	        boolean dbl = true;
1013	        for (int i = customerCode.length() - 1; i >= 0; i--) {
1014	            char c = customerCode.charAt(i);
1015	            if (c < '0' || c > '9') {
1016	                continue;
1017	            }
1018	            int d = c - '0';
1019	            if (dbl) {
1020	                d *= 2;
1021	                if (d > 9) {
1022	                    d -= 9;
1023	                }
1024	            }
1025	            sum += d;
1026	            dbl = !dbl;
1027	        }
1028	        return (10 - (sum % 10)) % 10;
1029	    }
1030	
1031	    /**
1032	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
1033	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
1034	     * is deterministic in the email.
1035	     *
1036	     * @param email the owner's email, possibly {@code null}
1037	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
1038	     */
1039	    public static String contactPreference(String email) {
1040	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
1041	    }
1042	
1043	    /**
1044	     * Compose an owner's {@code salutation} from the optional honorific title and the last name.
1045	     * When a title is present the result is the title and the last name separated by a single space
1046	     * (e.g. {@code 'DR Franklin'}); when no title is given the result is just the last name. The
1047	     * value is deterministic in those two fields.
1048	     *
1049	     * @param title the owner's honorific title, possibly {@code null} or blank
1050	     * @param lastName the owner's last name, possibly {@code null}
1051	     * @return the composed salutation
1052	     */
1053	    public static String salutation(String title, String lastName) {
1054	        if (title == null || title.isBlank()) {
1055	            return lastName;
1056	        }
1057	        return title + " " + lastName;
1058	    }
1059	
1060	    /**
1061	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
1062	     * date. The age in whole years is the number of completed years between {@code birthDate} and
1063	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
1064	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
1065	     * two fields and is only defined when both are present.
1066	     *
1067	     * @param birthDate the owner's date of birth, possibly {@code null}
1068	     * @param registrationDate the owner's registration date, possibly {@code null}
1069	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
1070	     *     is {@code null}
1071	     */
1072	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
1073	        if (birthDate == null || registrationDate == null) {
1074	            return null;
1075	        }
1076	        int age = Period.between(birthDate, registrationDate).getYears();
1077	        if (age < 18) {
1078	            return "MINOR";
1079	        }
1080	        if (age < 65) {
1081	            return "ADULT";
1082	        }
1083	        return "SENIOR";
1084	    }
1085	
1086	    protected Set<Pet> getPetsInternal() {
1087	        if (this.pets == null) {
1088	            this.pets = new HashSet<>();
1089	        }
1090	        return this.pets;
1091	    }
1092	
1093	    protected void setPetsInternal(Set<Pet> pets) {
1094	        this.pets = pets;
1095	    }
1096	
1097	    public List<Pet> getPets() {
1098	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
1099	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
1100	        return Collections.unmodifiableList(sortedPets);
1101	    }
1102	
1103	    public void setPets(List<Pet> pets) {
1104	        this.pets = new HashSet<>(pets);
1105	    }
1106	
1107	    public void addPet(Pet pet) {
1108	        getPetsInternal().add(pet);
1109	        pet.setOwner(this);
1110	    }
1111	
1112	    /**
1113	     * Return the Pet with the given name, or null if none found for this Owner.
1114	     *
1115	     * @param name to test
1116	     * @return true if pet name is already in use
1117	     */
1118	    public Pet getPet(String name) {
1119	        return getPet(name, false);
1120	    }
1121	
1122	    /**
1123	     * Return the Pet with the given name, or null if none found for this Owner.
1124	     *
1125	     * @param name to test
1126	     * @return true if pet name is already in use
1127	     */
1128	    public Pet getPet(String name, boolean ignoreNew) {
1129	        name = name.toLowerCase();
1130	        for (Pet pet : getPetsInternal()) {
1131	            if (!ignoreNew || !pet.isNew()) {
1132	                String compName = pet.getName();
1133	                compName = compName.toLowerCase();
1134	                if (compName.equals(name)) {
1135	                    return pet;
1136	                }
1137	            }
1138	        }
1139	        return null;
1140	    }
1141	
1142	    public Pet getPet(Integer petId) {
1143	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
1144	    }
1145	
1146	    @Override
1147	    public String toString() {
1148	        return new ToStringCreator(this)
1149	
1150	            .append("id", this.getId())
1151	            .append("new", this.isNew())
1152	            .append("lastName", this.getLastName())
1153	            .append("firstName", this.getFirstName())
1154	            .append("address", this.address)
1155	            .append("city", this.city)
1156	            .append("telephone", this.telephone)
1157	            .toString();
1158	    }
1159	}
